/*selectMasterMdCmCatalogRegProgressList*/ SELECT X.ITEM_FLAG, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTTP' AND CODE = NVL(X.ITEM_FLAG, 'I')) AS ITEM_FLAG_TEXT, X.CA_REQ_NO, X.CA_REQ_SEQ, X.CA_REQ_REVISION, X.CT_NO, X.STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTST' AND CODE = X.STATUS) AS STATUS_TEXT, X.CQDT_STATUS, DECODE(X.CQDT_STATUS, 'D', '삭제', 'C', '승인', 'R', '승인', '') AS CQDT_STATUS_TEXT, X.REQ_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTREQ' AND CODE = X.REQ_TYPE) AS REQ_TYPE_TEXT, X.K_REG_YN, X.BUYER, X.BUYER_ITEM_NO, X.ANOTHER_OFFER_FLAG, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTREP' AND CODE = X.ANOTHER_OFFER_FLAG) AS ANOTHER_OFFER_FLAG_TEXT, X.ANOTHER_OFFER_NOTE, X.CATEGORY_NO, (SELECT CATEG_NAME FROM ICOMBYCA WHERE STD_CATEG_ID = X.CATEGORY_NO AND COM_CODE = X.BUYER AND STATUS <> 'D') AS CATEG_NAME, X.BF_CATEGORY_NO, (SELECT CATEG_NAME FROM ICOMBYCA WHERE STD_CATEG_ID = X.BF_CATEGORY_NO AND COM_CODE = X.BUYER) AS BF_CATEG_NAME, X.DESCRIPTION, X.BF_DESCRIPTION, X.SPECIFICATION, X.BF_SPECIFICATION, X.MAKER_PART_NO, X.BF_MAKER_PART_NO, X.AGENT_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.AGENT_CODE AND STATUS IN ('C','R')) AS AGENT_CODE_TEXT, X.BF_AGENT_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BF_AGENT_CODE) AS BF_AGENT_CODE_TEXT, X.UNIT_MEASURE, X.BF_UNIT_MEASURE, X.UNIT_PRICE, X.BF_UNIT_PRICE, X.LIST_PRICE, X.BF_LIST_PRICE, X.DELIVERY_LT, X.BF_DELIVERY_LT, X.REMARK, X.CONTRACT_NO, X.CONTRACT_SEQ, X.IMGFILE_NAME, X.BF_IMGFILE_NAME, X.IMGFILE_DIR, X.BF_IMGFILE_DIR, X.BELOW_COMORG_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BELOW_COMORG_CODE AND STATUS IN ('C','R')) AS BUYER_TEXT, X.PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = X.PROCESS_TYPE) AS PROCESS_TYPE_TEXT, X.BF_PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = X.BF_PROCESS_TYPE) AS BF_PROCESS_TYPE_TEXT, X.ORIGIN_CODE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = X.ORIGIN_CODE) AS ORIGIN_CODE_TEXT, X.BF_ORIGIN_CODE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = X.BF_ORIGIN_CODE) AS BF_ORIGIN_CODE_TEXT, X.ORIGIN_AGENT, X.ORIGIN_AGENT_ERR, X.BF_ORIGIN_AGENT, X.PRODUCT_CLOSE_FLAG, X.SELLER_ITEM_NO, X.BF_SELLER_ITEM_NO, X.MAKER_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = X.MAKER_CODE) AS MAKER_CODE_TEXT, X.BF_MAKER_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = X.BF_MAKER_CODE) AS BF_MAKER_CODE_TEXT, X.CMS_CATEG_ID, (SELECT CATEG_NAME FROM CMSCATEG WHERE CMS_CATEG_ID = X.CMS_CATEG_ID) AS CMS_CATEG_TEXT, X.BF_CMS_CATEG_ID, (SELECT CATEG_NAME FROM CMSCATEG WHERE CMS_CATEG_ID = X.BF_CMS_CATEG_ID) AS BF_CMS_CATEG_TEXT, X.CMS_CATLG_ID, X.BF_CMS_CATLG_ID, X.KEP_DESCRIPTION, X.KEP_SPECIFICATION, X.KEP_UNIT_MEASURE, X.KEP_MAKER_NAME, X.KEP_ORIGIN_NAME, X.KEP_MAKER_PART_NO, X.KEP_MAKER_CODE, X.KEP_ORIGIN_CODE, X.ITEM_MAKE_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = X.ITEM_MAKE_TYPE) AS ITEM_MAKE_TYPE_TEXT, X.BF_ITEM_MAKE_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = X.BF_ITEM_MAKE_TYPE) AS BF_ITEM_MAKE_TYPE_TEXT, X.TO_DATE, X.BF_TO_DATE, X.BUY_CLOSE_DATE, X.BF_BUY_CLOSE_DATE, X.MIN_ORDER_QTY, X.BF_MIN_ORDER_QTY, X.PUR_UNIT_QTY, X.BF_PUR_UNIT_QTY, X.SELLER_AREA, X.TAX_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'TX17' AND CODE = X.TAX_TYPE) AS TAX_TYPE_TEXT, X.DESCRIPTION_ENG, X.SPECIFICATION_ENG, X.LOGISTICS_FEE, X.BF_LOGISTICS_FEE, X.LOGIS_RATE_STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'LGST' AND CODE = X.LOGIS_RATE_STATUS) AS LOGIS_RATE_STATUS_TEXT, X.BF_LOGIS_RATE_STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'LGST' AND CODE = X.BF_LOGIS_RATE_STATUS) AS BF_LOGIS_RATE_STATUS_TEXT, X.BUY_GREEN_ITEM_NM, X.BUY_GREEN_ITEM_CNO, X.BUY_GREEN_ITEM_FROM_DATE, X.BUY_GREEN_ITEM_TO_DATE, X.REQ_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.REQ_USER_ID) AS REQ_USER_NAME, X.REQ_DATE, X.RECV_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.RECV_USER_ID) AS RECV_USER_NAME, X.RECV_DATE, X.SO_SEND_DATE, X.SO_SEND_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.SO_SEND_USER_ID) AS SO_SEND_USER_NAME, X.RSO_REQ_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.RSO_REQ_USER_ID) AS RSO_REQ_USER_NAME, X.RSO_REQ_DATE, X.RSO_REQ_NOTE, X.UNIT_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.UNIT_USER_ID) AS UNIT_USER_NAME, X.SEL_SEND_DATE, X.CANCLE_REMARK, X.ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.ADD_USER_ID) AS ADD_USER_NAME, X.ADD_DATE, X.CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.CHANGE_USER_ID) AS CHANGE_USER_NAME, X.CHANGE_DATE FROM ( SELECT (SELECT NVL(ITEM_FLAG, 'I') FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS ITEM_FLAG, A.CA_REQ_NO, A.CA_REQ_SEQ, A.CA_REQ_REVISION, A.CT_NO, A.STATUS, (SELECT STATUS FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS CQDT_STATUS, A.REQ_TYPE, (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND BUYER_ITEM_NO = A.BUYER_ITEM_NO AND BELOW_COMORG_CODE = A.BELOW_COMORG_CODE) AS K_REG_YN, A.BUYER, A.BUYER_ITEM_NO, A.ANOTHER_OFFER_FLAG, A.ANOTHER_OFFER_NOTE, A.CATEGORY_NO, (SELECT CATEGORY_NO FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_CATEGORY_NO, A.DESCRIPTION, (SELECT DESCRIPTION_LOC FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_DESCRIPTION, A.SPECIFICATION, (SELECT SPECIFICATION FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_SPECIFICATION, A.MAKER_PART_NO, (SELECT MAKER_PART_NO FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_MAKER_PART_NO, A.AGENT_CODE, (SELECT AGENT FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_AGENT_CODE, A.UNIT_MEASURE, (SELECT UNIT_MEASURE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_UNIT_MEASURE, A.UNIT_PRICE, (SELECT UNIT_PRICE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_UNIT_PRICE, A.LIST_PRICE, (SELECT LIST_PRICE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_LIST_PRICE, A.DELIVERY_LT, (SELECT DELIVERY_LT FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_DELIVERY_LT, A.REMARK, A.CONTRACT_NO, A.CONTRACT_SEQ, A.IMGFILE_NAME, (SELECT IMGFILE_NAME FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_IMGFILE_NAME, A.IMGFILE_DIR, (SELECT IMGFILE_DIR FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_IMGFILE_DIR, A.BELOW_COMORG_CODE, A.PROCESS_TYPE, (SELECT DECODE(COUNT(*), 0, 'Y', 'N') FROM ICOMCMPY WHERE COM_CODE = A.ORIGIN_AGENT AND BUSINESS_COND = 'B' AND STATUS IN ('C', 'R')) AS ORIGIN_AGENT_ERR, (SELECT PROCESS_TYPE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_PROCESS_TYPE, A.ORIGIN_CODE, (SELECT ORIGIN_CODE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_ORIGIN_CODE, A.ORIGIN_AGENT, (SELECT ORIGIN_AGENT FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_ORIGIN_AGENT, A.PRODUCT_CLOSE_FLAG, A.SELLER_ITEM_NO, (SELECT SELLER_ITEM_NO FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_SELLER_ITEM_NO, A.MAKER_CODE, (SELECT MAKER_CODE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_MAKER_CODE, A.CMS_CATEG_ID, (SELECT CMS_CATEG_ID FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_CMS_CATEG_ID, A.CMS_CATLG_ID, (SELECT CMS_CATLG_ID FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_CMS_CATLG_ID, A.KEP_DESCRIPTION, A.KEP_SPECIFICATION, A.KEP_UNIT_MEASURE, A.KEP_MAKER_NAME, A.KEP_ORIGIN_NAME, A.KEP_MAKER_PART_NO, A.KEP_MAKER_CODE, A.KEP_ORIGIN_CODE, A.ITEM_MAKE_TYPE, (SELECT ITEM_MAKE_TYPE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_ITEM_MAKE_TYPE, A.TO_DATE, (SELECT SELL_CLOSE_DATE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_TO_DATE, A.BUY_CLOSE_DATE, (SELECT BUY_CLOSE_DATE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_BUY_CLOSE_DATE, A.MIN_ORDER_QTY, (SELECT MIN_ORDER_QTY FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_MIN_ORDER_QTY, A.PUR_UNIT_QTY, (SELECT PUR_UNIT_QTY FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_PUR_UNIT_QTY, A.SELLER_AREA, A.TAX_TYPE, A.DESCRIPTION_ENG, A.SPECIFICATION_ENG, A.LOGISTICS_FEE, (SELECT LOGISTICS_FEE FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_LOGISTICS_FEE, A.LOGIS_RATE_STATUS, (SELECT LOGIS_RATE_STATUS FROM ICOMCQDT WHERE BUYER = A.BUYER AND CONTRACT_NO = A.CONTRACT_NO AND CONTRACT_SEQ = A.CONTRACT_SEQ AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) AS BF_LOGIS_RATE_STATUS, A.BUY_GREEN_ITEM_NM, A.BUY_GREEN_ITEM_CNO, A.BUY_GREEN_ITEM_FROM_DATE, A.BUY_GREEN_ITEM_TO_DATE, A.REQ_USER_ID, TO_CHAR(A.REQ_DATE, 'YYYY/MM/DD HH24:MI:SS') AS REQ_DATE, A.RECV_USER_ID, TO_CHAR(A.RECV_DATE, 'YYYY/MM/DD HH24:MI:SS') AS RECV_DATE, TO_CHAR(A.SO_SEND_DATE, 'YYYY/MM/DD HH24:MI:SS') AS SO_SEND_DATE, A.SO_SEND_USER_ID, A.RSO_REQ_USER_ID, TO_CHAR(A.RSO_REQ_DATE, 'YYYY/MM/DD HH24:MI:SS') AS RSO_REQ_DATE, A.RSO_REQ_NOTE, A.UNIT_USER_ID, TO_CHAR(A.SEL_SEND_DATE, 'YYYY/MM/DD HH24:MI:SS') SEL_SEND_DATE, A.CANCLE_REMARK, A.ADD_USER_ID, TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD HH24:MI:SS') AS ADD_DATE, A.CHANGE_USER_ID, TO_CHAR(A.CHANGE_DATE, 'YYYY/MM/DD HH24:MI:SS') AS CHANGE_DATE FROM KEP_CA_CREATE A WHERE 1=1 AND TO_CHAR(A.REQ_DATE, 'YYYYMMDD') BETWEEN REPLACE(#{st_from_date}, '/', '') AND REPLACE(#{st_to_date}, '/', '') AND A.STATUS <> 'D'
AND A.BELOW_COMORG_CODE = #{st_buyer_code}
AND A.REQ_TYPE = #{st_req_type}
AND A.BUYER_ITEM_NO LIKE '%' || UPPER(#{st_buyer_item_no}) || '%'
AND A.DESCRIPTION LIKE '%' || UPPER(#{st_description}) || '%'
AND A.SPECIFICATION LIKE '%' || UPPER(#{st_specification}) || '%'
AND A.STATUS = #{st_status}
AND A.CT_NO LIKE '%' || UPPER(#{st_contract_no}) || '%'
) X ORDER BY X.CA_REQ_NO, X.CA_REQ_SEQ, X.CA_REQ_REVISION, X.REQ_TYPE

mapper.update:

/*updateMasterMdCmCatalogRegUnitPrice*/
	UPDATE	KEP_CA_CREATE
	SET		UNIT_USER_ID = #{st_user_id},
			CHANGE_USER_ID = #{st_user_id}
	WHERE	1=1
	AND		CA_REQ_NO = #{CA_REQ_NO}
	AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
	AND		CA_REQ_REVISION = #{CA_REQ_REVISION}
	AND		STATUS = 'S'


/*updateMasterMdCmCatalogRegSourcing*/
	UPDATE	KEP_CA_CREATE
	SET		SO_SEND_USER_ID = #{st_user_id},
			CHANGE_USER_ID = #{st_user_id}
	WHERE	1=1
	AND		CA_REQ_NO = #{CA_REQ_NO}
	AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
	AND		CA_REQ_REVISION = #{CA_REQ_REVISION}
	AND		STATUS = 'R'


/*deleteMasterMdCmCatalogRegProgress*/
	UPDATE	KEP_CA_CREATE
	SET		STATUS = 'D',
			CANCLE_REMARK = #{CANCLE_REMARK},
			CHANGE_USER_ID = #{st_user_id},
			CHANGE_DATE = SYSDATE
	WHERE	1=1
	AND		CA_REQ_NO = #{CA_REQ_NO}
	AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
	AND		CA_REQ_REVISION = #{CA_REQ_REVISION}
	AND		BUYER = #{BUYER}

mapper.select:

/*selectMasterMdCmCatalogRegSourcingChk*/
SELECT	NVL(COUNT(*),0)
FROM	KEP_CA_CREATE
WHERE	1=1
AND		CA_REQ_NO = #{CA_REQ_NO}
AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
AND		CA_REQ_REVISION = #{CA_REQ_REVISION}
AND		STATUS IN ('Q', 'R')


/*selectMasterMdCmCatalogRegUnitPriceChk*/
SELECT	NVL(COUNT(*),0)
FROM	KEP_CA_CREATE
WHERE	1=1
AND		CA_REQ_NO = #{CA_REQ_NO}
AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
AND		CA_REQ_REVISION = #{CA_REQ_REVISION}
AND		STATUS = 'S'

mapper.update:

/*batchMasterMdCmCatalogRegUnitPrice*/
	UPDATE	KEP_CA_CREATE
	SET		UNIT_PRICE = #{UNIT_PRICE},
			TO_DATE = TO_CHAR(TO_DATE(#{TO_DATE}, 'YYYYMMDD'), 'YYYYMMDD'),
			CHANGE_USER_ID = #{st_user_id},
			CHANGE_DATE = SYSDATE
	WHERE	1=1
	AND		CA_REQ_NO = #{CA_REQ_NO}
	AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
	AND		CA_REQ_REVISION = #{CA_REQ_REVISION}
	AND		STATUS = 'S'


/*saveMasterMdCmCatalogRegRevision*/
	UPDATE	KEP_CA_REVISION
	SET		STATUS = 'O'
	WHERE	1=1
	AND		CA_REQ_NO = #{CA_REQ_NO}
	AND		CA_REQ_SEQ = #{CA_REQ_SEQ}
	AND		CA_REQ_REVISION = #{CA_REQ_REVISION} -1
	AND		STATUS = 'C'
